/bin/bash -lc "node --input-type=module <<'NODE'
import {createServer} from 'vite';
import React from 'react';
import {renderToString} from 'react-dom/server';
import assert from 'node:assert/strict';
const vite = await createServer({server: {middlewareMode: true}, appType: 'custom'});
try {
  const {App} = await vite.ssrLoadModule('/src/App.tsx');
  const render = () => renderToString(React.createElement(App));
  globalThis.localStorage = {getItem: () => null};
  const russian = render();
  for (const label of ['Настройки профиля', 'Новости продукта', 'Системные алерты', 'Дайджест за неделю', 'Сохранить', 'Отмена']) assert.ok(russian.includes(label), label);
  assert.ok(russian.includes('alex.smirnov@gmail.com'));
  assert.equal((russian.match(/type=\"checkbox\"/g) || []).length, 4);
  globalThis.localStorage = {getItem: () => JSON.stringify({name: 'Jane Doe', email: 'jane@example.com', language: 'en', twoFactor: true})};
  const english = render();
  assert.ok(english.includes('Profile settings'));
  assert.ok(english.includes('Jane Doe'));
  assert.ok(english.includes('jane@example.com'));
  globalThis.localStorage = {getItem: () => '{invalid json'};
  assert.ok(render().includes('Настройки профиля'));
  globalThis.localStorage = {getItem: () => {throw Error('Storage unavailable');}};
  assert.ok(render().includes('Настройки профиля'));
  console.log('Render checks passed: all fields, notification controls, persisted English profile, corrupted and unavailable storage.');
} finally { await vite.close(); }
NODE"

